\begin{lemma}\label{l:dry}
Suppose that $\phi\colon \mathcal{H}\to \left(-\infty, +\infty\right]$ satisfies the dry-like friction property with constant $r$. Let $y \in \mathcal{H}$ and $w \in \prox_{\tau \phi}(y)$. Then $\langle w-y, w\rangle  + r\tau \|w\| \leq 0.$
\end{lemma}

\begin{proof}
Since $w \in \prox_{\tau \phi}(y) = \argmin_{x \in \mathcal{H}} \left(\phi(x) +\frac{1}{2 \tau}\|x-y\|^2\right)$, we have $0 \in \partial \phi(w) + \frac{1}{\tau}(w-y)$, which yields $\frac{1}{\tau}(y-w) \in \partial \phi(w)$, and so $w \in \dom \partial \phi$. By the dry-like friction property of $\phi$, $\frac{1}{\tau}\langle y -w, w\rangle \geq r\|w\|$, which completes the proof.
\end{proof}

\begin{lemma}
% [Descent property of the potential function]
\label{l:descent}
Suppose that $f$ is a differentiable function whose gradient is $L$-Lipschitz continuous. Under the setting of AGDNL algorithm, for all $n \in \N$, the following hold:
\begin{enumerate}
\item\label{l:descent_wn}
$\|w_n\|^2 - \mu \alpha_n \langle w_{n-1}, w_n\rangle  +\kappa_n \langle \nabla f(u_n), w_n\rangle  +\delta \| w_n\| \leq 0$. Consequently, $\|w_n\|^2 + (\delta - k_{\max} \|\nabla f(u_n)\| - \mu  \bar \alpha\|w_{n-1}\|) \|w_n\| \leq 0$. 
\item\label{l:descent_Vn}
If $L_n \geq L$, $L_n \beta_n \leq L_{n-1} \beta_{n-1}$, $\gamma_n \leq \gamma_{n-1}$, $\frac{\gamma_n}{\nu_n} \leq \frac{\gamma_{n-1}}{\nu_{n-1}}$, and $\frac{\alpha_n}{\nu_n} \leq \frac{\alpha_{n-1}}{\nu_{n-1}}$, then
\begin{align*}%\label{eq:KL1}
&V(z_{n+1}, x_n, w_n,\rho_n, \sigma_n) + \frac{c_n}{\nu_n}\|z_{n+1} -x_n||^2 +  \frac{d_n}{\nu_n}\|\nabla f(u_n)\|^2 + \frac{\delta}{\nu_n} \| w_n\| \\
&\leq V(x_n, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}),
\end{align*}  
where
\begin{align}
c_n &= \frac{(1 -\mu \bar\alpha) (1 -2\gamma_n )}{\mu^2} - \frac{(2 L_n\beta_n +\gamma_n + L_n)\nu_n }{2} \label{d:cn}\\
\text{and~~}
d_{n} &= \frac{2(1- \mu \bar\alpha)(\lambda_n^2 -\gamma_n\lambda_n)-\mu\gamma_n\kappa_n+2\mu\lambda_n \kappa_n}{2\mu^2} \label{d:dn}.
\end{align}
\end{enumerate}
\end{lemma}

\begin{proof}
\ref{l:descent_wn}:
Set $y_n = \alpha_n(x_n -v_{n-1}+\lambda_n\nabla f(u_{n-1}))-\theta_n \frac{\nabla f(u_n)}{\|\nabla f(u_n)\|}-\kappa_n \nabla f(u_n)+ e_n$. By the update of $x_n$, we have $\mu w_{n-1}= x_n - v_{n-1} +\lambda_{n-1} \nabla f(u_{n-1})$, and so
\begin{equation*}
y_n = \alpha_n\mu w_{n-1} -\theta_n \frac{\nabla f(u_n)}{\|\nabla f(u_n)\|} -\kappa_n \nabla f(u_n)+ e_n.
\end{equation*}
By Step~\ref{step:main}\ref{step:main_comp}, $w_n \in \prox_{\tau_n \phi}(y_n)$. Since $\phi$ satisfies the dry-like friction property with constant $r$, we have from Lemma~\ref{l:dry} that $\langle w_n-y_n, w_n\rangle  + r\tau_n \|w_n\| \leq 0$, which yields
\begin{equation*}
\|w_n\|^2 - \alpha_n \mu\langle w_{n-1}, w_n\rangle  + \kappa_n \langle \nabla f(u_n), w_n\rangle  + (r\tau_n - |\theta_n| - \|e_n\|)\| w_n\| \leq 0.    
\end{equation*}
Combining this with $r\tau_n \geq |\theta_n| +\|e_n\| +\delta$, we get the first conclusion, which implies the second one.

\ref{l:descent_Vn}: Set $\Delta_n = x_n - x_{n-1}$. It follows from the update of $z_{n+1}$ that
\begin{equation*}
\mu w_n=z_{n+1} -v_n +\lambda_n \nabla f(u_n) 
=(z_{n+1} -x_n)-\gamma_n \Delta_n +\lambda_n \nabla f(u_n),    
\end{equation*}
and so
\begin{align}\label{eq:57}
\mu^2\|w_n\|^2&=  \|z_{n+1} -x_n\|^2 +\gamma_n^2 \|\Delta_n\|^2 +\lambda_n^2 \|\nabla f(u_n)\|^2 - 2\gamma_n \langle z_{n+1} -x_n,  \Delta_n\rangle \notag\\
 & \quad +2  \lambda_n\langle z_{n+1} -x_n, \nabla f(u_n)\rangle -2 \gamma_n\lambda_n\langle  \Delta_n, \nabla f(u_n) \rangle \notag\\
 &\geq  \|z_{n+1} -x_n\|^2 +\gamma_n^2 \|\Delta_n\|^2 +\lambda_n^2 \|\nabla f(u_n)\|^2 - \gamma_n (\|z_{n+1}-x_n\|^2 + \|\Delta_n\|^2)  \notag\\
  & \quad +2 \lambda_n\langle z_{n+1} -x_n, \nabla f(u_n)\rangle - \gamma_n\lambda_n(\|\Delta_n\|^2 + \|\nabla f(u_n)\|^2) \notag\\
  &=  (1-\gamma_n)\|z_{n+1} -x_n\|^2 +(\gamma_n^2-\gamma_n -\gamma_n\lambda_n) \|\Delta_n\|^2 + (\lambda_n^2 -\gamma_n\lambda_n) \|\nabla f(u_n)\|^2 \notag\\
   & \quad +2 \lambda_n\langle z_{n+1} -x_n, \nabla f(u_n)\rangle.
\end{align}
Since $\nabla f$ is $L$-Lipschitz continuous, $L_n \geq L$, and $u_n = x_n + \beta_n(x_n - x_{n-1})$, we have
\begin{align}\label{eq:es2}
\langle \nabla f(u_n), z_{n+1} -x_n \rangle &= \langle \nabla f(u_n) - \nabla f(x_n), z_{n+1} - x_{n} \rangle + \langle \nabla f(x_n), z_{n+1} -x_n \rangle \notag\\
& \geq -L_n\|u_n -x_n\| \|z_{n+1} -x_n\| + f(z_{n+1}) -f(x_n) -\frac{L_n}{2}\|z_{n+1} - x_n\|^2 \notag\\
% & \geq -\frac{L_n\beta_n}{2}(\|\Delta_n\|^2 + \|z_{n+1}-x_n\|^2) + f(z_{n+1}) -f(x_n) -\frac{L_n}{2}\|z_{n+1} -x_n\|^2\notag\\
& \geq  -\frac{L_n\beta_n}{2}\|\Delta_n\|^2 -\frac{L_n\beta_n +L_n}{2}\|z_{n+1} -x_n\|^2 + f(z_{n+1}) -f(x_n).
\end{align}
Combining this with \eqref{eq:57}, we derive that
\begin{align}\label{eq:es1}
 &\|w_n\|^2 - \mu \alpha_n \langle w_{n-1}, w_n\rangle+\kappa_n \langle \nabla f(u_n), w_n\rangle \notag\\
&\geq \|w_n\|^2 - \frac{\mu \alpha_n}{2}(\|w_n\|^2 +\|w_{n-1}\|^2)+\kappa_n \langle \nabla f(u_n), w_n\rangle \notag\\
& \geq  -\frac{\mu \alpha_{n}}{2} \|w_{n-1}\|^2 +\frac{\mu \alpha_n}{2} \|w_n\|^2 +(1-\mu \bar\alpha)\|w_n\|^2\notag\\
&\quad+\frac{\kappa_n }{\mu} \langle \nabla f(u_n), z_{n+1} -x_n \rangle -\frac{\gamma_n\kappa_n }{\mu} \langle \nabla f(u_n), \Delta_n \rangle +\frac{\lambda_n \kappa_n }{\mu}\|\nabla f(u_n)\|^2\notag\\
& \geq  -\frac{\mu \alpha_{n}}{2} \|w_{n-1}\|^2  +\frac{\mu \alpha_n}{2} \|w_n\|^2 \notag\\
& \quad +\frac{1-\mu \bar\alpha }{\mu^2}\left( (1-\gamma_n)\|z_{n+1} -x_n\|^2 +(\gamma_n^2-\gamma_n -\gamma_n\lambda_n) \|\Delta_n\|^2 + (\lambda_n^2 -\gamma_n\lambda_n) \|\nabla f(u_n)\|^2  \right)\notag\\
  & \quad+ \frac{2\lambda_n(1-\mu \bar\alpha)}{\mu^2}\langle z_{n+1} -x_n, \nabla f(u_n)\rangle +\frac{\kappa_n}{\mu} \langle \nabla f(u_n), z_{n+1} -x_n \rangle  \notag\\
  &\quad -\frac{\gamma_n \kappa_n }{2\mu} (\|\nabla f(u_n)\|^2 +\|\Delta_n \|^2) +\frac{\lambda_n\kappa_n }{\mu}\|\nabla f(u_n)\|^2\notag\\
&\geq -\frac{\mu \alpha_{n}}{2} \|w_{n-1}\|^2 +\frac{\mu \alpha_n}{2} \|w_n\|^2 +\bar c_n\|z_{n+1}-x_n\|^2 -\tilde c_n\|\Delta_n\|^2+ d_n\|\nabla f(u_n)\|^2\notag\\
&\quad +\left(\frac{2\lambda_n(1-\mu \bar\alpha)}{\mu^2} +\frac{\kappa_n }{\mu}\right)( f(z_{n+1}) -f(x_n)), 
\end{align}
where the last inequality follows from \eqref{eq:es2}, $d_n$ is defined in \eqref{d:dn} and
\begin{align}
\bar c_n &=\frac{(1-\mu \bar\alpha) (1-\gamma_n)}{\mu^2} -\frac{L_n\beta_n + L_n}{2 }  \left(\frac{2\lambda_n(1-\mu \bar\alpha)}{\mu^2}+ \frac{\kappa_n}{\mu}\right), \notag\\
\tilde c_n  &=\frac{(1 -\mu \bar\alpha)\left(\gamma_n +\gamma_n\lambda_n+L_n\lambda_n \beta_n \right)  + \frac{\mu \kappa_n}{2}(L_n\beta_n +\gamma_n)}{\mu^2} \notag\\
&=\frac{(1 -\mu \bar\alpha)\gamma_n}{\mu^2} + \frac{ L_n\beta_n +\gamma_n}{2 } \left(\frac{2\lambda_n(1-\mu \bar\alpha)}{\mu^2}+ \frac{\kappa_n}{\mu}\right) =\rho_n \nu_n.\label{d:eta} 
\end{align}
It follows from \ref{l:descent_wn}, \eqref{eq:es1}, and the definition of $\nu_n$ that
\begin{align*}
&\frac{\mu \alpha_n}{2} \|w_n\|^2 -\frac{\mu \alpha_n}{2}\|w_{n-1}\|^2  +  \nu_n(f(z_{n+1}) -f(x_n))+ \bar c_n \|z_{n+1} -x_n||^2  - \rho_n \nu_n\|\Delta_{n}\|^2 \notag\\
& + d_n\|\nabla f(u_n)\|^2 + \delta \| w_n\|  \leq 0,
\end{align*}
which implies that
\begin{align}\label{eq:ADFGe_4}
 &f(z_{n+1})+ \rho_n \|z_{n+1} -x_n||^2 + \frac{\mu \alpha_n}{2\nu_n} \|w_n\|^2 + \frac{c_n}{\nu_n}\|z_{n+1} -x_n||^2 +  \frac{d_n}{\nu_n}\|\nabla f(u_n)\|^2 \notag\\
 &\hspace{3cm} + \frac{\delta}{\nu_n} \| w_n\| \leq f(x_n)+ \rho_n \|x_n -x_{n-1}||^2 + \frac{\mu \alpha_n}{2 \nu_n} \|w_{n-1}\|^2.
  \end{align}  
Here, we note that
\begin{align*}
\bar c_n-\rho_n \nu_n&= \frac{(1 -\mu \bar\alpha) (1 -2\gamma_n )}{\mu^2} - \frac{2 L_n\beta_n +\gamma_n + L_n}{2} \left(\frac{2\lambda_n(1-\mu \bar\alpha)}{\mu^2}+ \frac{\kappa_n}{\mu}\right) \\
&= \frac{(1 -\mu \bar\alpha) (1 -2\gamma_n )}{\mu^2} - \frac{(2 L_n\beta_n +\gamma_n + L_n)\nu_n}{2}  =c_n.
\end{align*}
Since $L_n \beta_n \leq L_{n-1}\beta_{n-1}$, $\gamma_n \leq \gamma_{n-1}$, and $\frac{\gamma_n}{\nu_n} \leq \frac{\gamma_{n-1}}{\nu_{n-1}}$, we have $\rho_n \leq \rho_{n-1}$. As $\frac{\alpha_n}{\nu_n} \leq \frac{\alpha_{n-1}}{\nu_{n-1}}$, using \eqref{eq:ADFGe_4} and the definition of $V$ in \eqref{eq:V}, we get the conclusion. 
\end{proof}

\begin{lemma}[Well-definedness of the line search criterion]
Suppose that $f$ is a differentiable function whose gradient is $L$-Lipschitz continuous. Then, for all $n \in \N$, the line search criterion \eqref{eq:linesearch} in AGDNL algorithm is satisfied after a finite number of inner iterations.
\end{lemma}

\begin{proof}
Fix $n \in \mathbb{N}$. Since $\ell_1 \in (0, 1)$ and $\tilde{L}_n > L_{\min}$, there exists $k_0$ such that $\ell_1^{-k_0}\tilde L_n\geq L_{\max}$. It also can be seen that there exists $k_1$ such that $\ell_3^{k_1} \tilde{\lambda}_n \leq \lambda_{\min}$ and $\ell_3^{k_1} \tilde{\kappa}_n \leq \kappa_{\min}$ since $\ell_3 \in (0,1)$. Suppose that the line search criterion \eqref{eq:linesearch} is not satisfied after $\max\{k_0, k_1\}$ inner iterations. At the $k$-th inner iteration with $k >\max\{k_0, k_1\}$, by Step~\ref{step:main}\ref{step:main_mult},
\begin{equation}\label{eq:kth}
L_n = L_{\max}, \quad \gamma_n =\ell_{2}^{k} \tilde{\gamma}_n, \quad \alpha_n =\ell_{2}^{k} \tilde{\alpha}_n, \quad \beta_n =\ell_{2}^{k} \tilde{\beta}_n, \quad \lambda_n = \lambda_{\min}, \text{~and~} \kappa_n =\kappa_{\min}.
\end{equation}
Then $\nu_n = \frac{2 \lambda_{\min}(1 -\mu \bar \alpha)}{\mu^2}+ \frac{\kappa_{\min} }{\mu} = \underline{\nu}$, and so $\frac{\gamma_n}{\nu_n} =\frac{\ell_2^k\tilde{\gamma}_n}{\nu_n} =\frac{\ell_2^k\tilde{\gamma}_n}{\underline{\nu}}$ and $\frac{\alpha_n}{\nu_n} =\frac{\ell_2^k\tilde{\alpha}_n}{\nu_n} =\frac{\ell_2^k \tilde{\alpha}_n}{\underline{\nu}}$. Since $0<\ell_2 <1$, there exists $k_2 >\max\{k_0, k_1\}$ such that after $k_2$ inner iterations, $\gamma_n \leq \gamma_{n-1}$, $L_n \beta_n = L_{\max} \ell_{2}^{k} \tilde{\beta}_n  \leq L_{n-1} \beta_{n-1}$,  $\frac{\gamma_n}{\nu_n} \leq \frac{\gamma_{n-1}}{\nu_{n-1}}$, and $\frac{\alpha_n}{\nu_n} \leq \frac{\alpha_{n-1}}{\nu_{n-1}}$.
Using Lemma~\ref{l:descent} and noting that $\nu_n =\underline{\nu}$, we get
\begin{align}
\label{eq:lsV}
&V(z_{n+1}, x_n, w_n,\rho_n, \sigma_n) + \frac{c_n}{\underline{\nu}}\|z_{n+1} -x_n||^2 +  \frac{d_n}{\underline{\nu}}\|\nabla f(u_n)\|^2 + \frac{\delta}{\underline{\nu}} \| w_n\| \notag \\
&\leq V(x_n, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}).
\end{align}
It follows from \eqref{eq:kth} and the definition of $c_n$ in \eqref{d:cn} that
\begin{align}\label{eq:cn}
c_n&= \frac{(1 -\mu \bar\alpha) (1 -2\ell_{2}^{k} \tilde{\gamma}_n)}{\mu^2} - \frac{( 2 \ell_{2}^{k}L_{\max} \tilde{\beta}_n +\ell_{2}^{k}\tilde{\gamma}_n + L_{\max})\underline{\nu}}{2} \notag\\
&= \frac{ 1-\mu \bar\alpha}{\mu^2}- \frac{L_{\max} \underline{\nu}}{2}-\ell_2^k \left[ \frac{2\tilde{\gamma}_n (1-\mu \bar\alpha)}{\mu^2}  + \frac{2L_{\max}\tilde{\beta}_n \underline{\nu} +\tilde{\gamma}_n\underline{\nu}}{2} \right]\notag\\
&=\bar c \underline{\nu} -\ell_2^k \left[ \frac{2\tilde{\gamma}_n (1-\mu \bar\alpha)}{\mu^2}  + \frac{2L_{\max}\tilde{\beta}_n \underline{\nu} +\tilde{\gamma}_n\underline{\nu}}{2} \right].
\end{align}
Since $c \leq \bar c=\frac{2(1-\mu \bar \alpha) - \mu^2 L_{\max} \underline{\nu}}{2 \mu^2 \underline{\nu}}$, we consider two cases: $c <\bar c$ and $c = \bar c$. If $c <\bar c$, using \eqref{eq:cn} and the fact that $0< \ell_{2} <1$, there exists $k_3$ such that after $k_3$ inner iterations, $c_n \geq c\underline{\nu}$. If $c = \bar c$, by the choice of $\gamma_n$, $\beta_n$ in Step~\ref{step:init} and Step~\ref{step:main}, for all $n \in \N$, $\tilde \gamma_n =0$ and $\tilde \beta_n =0$, which together with \eqref{eq:cn} yields $c_n \geq c\underline{\nu}$.

Now, we consider $d_n$. Using definition of $d_n$ and \eqref{eq:kth}, we have 
\begin{align*}
d_{n}&= \frac{2(1- \mu \bar\alpha)(\lambda_n^2 -\ell_{2}^k \tilde{\gamma}_n\lambda_n)-\mu \ell_{2}^{k}\tilde{\gamma}_n\kappa_n+2\lambda_n \mu \kappa_n }{2\mu^2}\notag\\
& = \frac{(1-\mu \bar\alpha)\lambda_{\min}^2 + \lambda_{\min} \mu \kappa_{\min}}{\mu^2} - \ell_2^k\frac{\tilde{\gamma}_n(2(1 -\mu \bar\alpha)\lambda_{\min} +\mu\kappa_{\min})}{2\mu^2} \notag\\
& =\bar d \underline{\nu} - \ell_2^k\frac{\tilde{\gamma}_n(2(1 -\mu \bar\alpha)\lambda_{\min} +\mu\kappa_{\min})}{2\mu^2}.
\end{align*}
By Step~\ref{step:init} and Step~\ref{step:main}, $d \in [0, \bar d]$ and if $d =\bar d$, then $\tilde{\gamma}_n =0$. Since $0<\ell_2 <1$, there exists $k_4$ such that after $k_4$ inner iterations, $d_{n} \geq d \underline{\nu}$. Hence, in view of \eqref{eq:lsV}, after at most $\max\{ k_2,k_3, k_4\}$ inner iterations, the line search criterion \eqref{eq:linesearch} holds.
\end{proof}

\begin{lemma}
\label{l:limit}
Let $f \colon \mathcal{H} \to \R$ be a continuous differentiable function. Let $(x_n)_{n \in \N}$ and $(u_n)_{n \in \N}$ be sequences in $\mathcal{H}$ such that $(x_n)_{n \in \N}$ is bounded and $x_n -u_n \to 0$ as $n \to +\infty$. Then $f(x_n) -f(u_n) \to 0$ as $n \to +\infty$.
\end{lemma}

\begin{proof}
By the mean value theorem, $f(x_n) -f(u_n) = \langle \nabla f(z_n), x_n -u_n \rangle$, where $z_n = x_n -\zeta_n (x_n -u_n)$ for some $\zeta_n \in [0,1]$. Then $(z_n)_{n \in \N}$ is bounded due to the assumptions on $(x_n)_{n \in \N}$ and $(u_n)_{n \in \N}$. This together with the continuity of $\nabla f$ implies the existence of $M$ such that, for all $n \in \N$, $\|\nabla f(z_n)\| \leq M$, which yields $|f(x_n) -f(u_n) | \leq M\|x_n -u_n\|$. Since $x_n -u_n \to 0$ as $n \to +\infty$, we obtain the conclusion.
\end{proof}

\begin{theorem}[Subsequential convergence and structural simplification]
\label{t:subseq}
Let $(x_n)_{n\in \mathbb{N}}$ be the sequence generated by AGDNL algorithm and $\Omega$ be the set of strong cluster points of $(x_n)_{n \in \N}$. Suppose that $f$ is a differentiable function whose gradient is $L$-Lipschitz continuous, that $f$ is bounded below, and that the set $\{x \in \mathcal{H}: f(x) \leq f(x_0) + \sigma_{-1}\|w_{-1}\|^2\}$ is bounded. Then the following hold:
\begin{enumerate}
\item\label{t:subseq_bounded}
$(x_n)_{n \in \N}$ is bounded.
\item\label{t:subseq_limit} 
As $ n \to +\infty$, $\|x_{n+1}-x_n\| \to 0$,  $\|w_n\| \to 0$, $f(x_n) \to \zeta$, and \\ $V(x_{n}, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}) \to \zeta$ for some $\zeta \in \mathbb{R}$. Moreover, for all $\bar x \in \Omega$, $ f(\bar x) =\zeta$.  
\item\label{t:subseq_simplify} 
Suppose that $\lambda_{\min} >0$. Then $\lim_{n \to +\infty } \nabla f(x_n) =0$ and for all $\bar x \in \Omega$, $\nabla f(\bar x) =0$. Moreover, from some $N_0 \in \N$ onwards, $w_n =0$ and AGDNL algorithm becomes AGNL algorithm.
\end{enumerate}
\end{theorem}

\begin{proof}
\ref{t:subseq_bounded}: First, we prove by induction that, for all $n \in \N$,
\begin{equation}\label{eq:bx1}
V(x_{n}, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}) \leq f(x_0) + \sigma_{-1}\|w_{-1}\|^2.
\end{equation}
Since $x_{-1} =x_0$, we have $V(x_{0}, x_{-1}, w_{-1},\rho_{-1},\sigma_{-1}) = f(x_0) + \sigma_{-1}\|w_{-1}\|^2$, so \eqref{eq:bx1} holds for $n=0$. Suppose that \eqref{eq:bx1} holds for all $n \leq n_0$. %We have $\sigma_{-1} =0$ since $\alpha_{-1} =0$.
From \eqref{eq:linesearch}, we obtain that
\begin{align*}
V(x_{n_0+1}, x_{n_0}, w_{n_0},\rho_{n_0}, \sigma_{n_0}) &\leq \max_{[n_0-N]_+ \leq k \leq n_0}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1})\notag\\
&\leq   f(x_0) + \sigma_{-1}\|w_{-1}\|^2,
\end{align*}
and hence \eqref{eq:bx1} is satisfied for $n=n_0+1$, which completes the induction. Next, it follows from \eqref{eq:bx1} and the definition of $V$ that $f(x_n) \leq  f(x_0) + \sigma_{-1}\|w_{-1}\|^2$. The conclusion now follows from the boundedness of the set $\{x \in \mathcal{H}: f(x) \leq f(x_0) + \sigma_{-1}\|w_{-1}\|^2\}$.

\ref{t:subseq_limit}: It follows from the line search criterion \eqref{eq:linesearch} that
\begin{align}\label{eq:lsx}
&V(x_{n+1}, x_n, w_n,\rho_n, \sigma_n) +c\|x_{n+1}-x_n\|^2  + d \|\nabla f(u_n)\|^2+ \frac{\delta}{\underline{\nu}}\| w_n\|\notag\\ &\leq \max_{[n-N]_+ \leq k \leq n}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1})\notag\\
&= V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}).
\end{align}
Therefore,
\begin{align*}
&V(x_{m(n+1)}, x_{m(n)}, w_{m(n)},\rho_{m(n)}, \sigma_{m(n)}) \notag\\
&= \max_{[n+1-N]_+ \leq k \leq n+1}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1})\notag\\
&=\max \left\{V(x_{n+1}, x_n, w_n,\rho_n, \sigma_n), \max_{[n+1-N]_+ \leq k \leq n}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1}) \right\}\notag\\
& \leq  \max_{[n-N]_+ \leq k \leq n}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1}) \notag\\
&=V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}),
\end{align*}
which implies that the sequence $(V(x_{m(n+1)}, x_{m(n)}, w_{m(n)},\rho_{m(n)}, \sigma_{m(n)}))_{n\in \N}$ is nonincreasing. On the other hand, this sequence is bounded below due to the bounded below property of $f$ and the definition of $V$. Thus, there exists $\zeta$ such that
\begin{equation}\label{eq:limV}
\zeta =\lim_{n \to +\infty}V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}).
\end{equation} 
%\ref{t:subseq_limit}
In \eqref{eq:lsx}, replacing $n$ by $m(n)-1$ yields
\begin{align*}
&V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}) +c\|x_{m(n)}-x_{m(n)-1}\|^2 \notag\\ 
&+d \|\nabla f(u_{m(n)-1})\|^2 +\frac{\delta}{\underline{\nu}}\| w_{m(n)-1}\| \notag\\
&\leq V(x_{m(m(n)-1)}, x_{m(m(n)-1)-1}, w_{m(m(n)-1)-1},\rho_{m(m(n)-1)-1}, \sigma_{m(m(n)-1)-1}).
\end{align*}
Letting $n \to +\infty$ and noting that $m(n) \geq [n-N]_{+}$, we get $ \lim_{n \to +\infty}\|w_{m(n)-1} \| = 0$. 
If $c >0 $, we also have $\lim_{n \to +\infty}\|x_{m(n)}-x_{m(n)-1}\|~=~0$. If $c=0$ and $d >0$, then $\lim_{n \to +\infty}\|\nabla f(u_{m(n)-1}) \| = 0$, which implies that 
\begin{equation*}
 |x_{m(n)} - x_{m(n)-1}\| =\|-\lambda_{m(n)-1}\nabla f(u_{m(n)-1}) + \mu w_{m(n)-1} \| \to 0 \text{~as~} n \to +\infty   
\end{equation*}
If $c=d=0$, then $\lambda_{\min} =0$ since  $d >0$ if $\lambda_{\min} >0$ and $c=0$. By Step~\ref{step:main}, for all $n \in \N$, $\lambda_n = \gamma_n =0$, and so $\lim_{n \to +\infty}\|x_{m(n)}-x_{m(n)-1}\| =\lim_{n \to +\infty}\mu \|w_{m(n)-1} \| =0$. Therefore, in any cases,
\begin{equation}\label{eq:indu1}
\lim_{n \to +\infty}\|x_{m(n)}-x_{m(n)-1}\| = 0 \text{~and~} \lim_{n \to +\infty}\|w_{m(n)-1} \| = 0.
\end{equation}
By the definitions of $\rho_n$ and $\sigma_n$, for all $n \in \N$,
$0\leq \rho_n \leq  \frac{1}{\mu^2}(1 -\mu \bar\alpha)\frac{\bar\gamma}{\underline{\nu}} + \frac{ L_{\max}\bar\beta +\bar\gamma}{2 }$ and $ 0\leq  \sigma_n \leq\frac{\mu \alpha_{\max}}{2 \underline{\nu}}.$ Combining with \eqref{eq:limV} and \eqref{eq:indu1}, we derive that
\begin{align*}
f(x_{m(n)})&=V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}) \notag\\
&\quad - \rho_{m(n)-1}\|x_{m(n)}-x_{m(n)-1}\|^2 - \sigma_{m(n)-1} \| w_{m(n)-1}\|^2
\end{align*}
also tends to $\zeta$ as $n \to +\infty$. Since $(x_n)_{n\in \N}$ is bounded and $\lim_{n \to +\infty}\|x_{m(n)}-x_{m(n)-1}\| = 0$, Lemma~\ref{l:limit} implies that 
\begin{equation}\label{eq:indu2}
\lim_{n \to +\infty}f(x_{m(n)-1})=\lim_{n \to +\infty}f(x_{m(n)}) = \zeta.
\end{equation}
Now, we prove by induction that for all $k \in [1, m(n)]$,
\begin{equation}\label{eq:indu}
\lim_{n \to +\infty}\|x_{m(n)-k+1}-x_{m(n)-k}\|=0 , \lim_{n \to +\infty} \|w_{m(n)-k}\|=0, \text{~and~} \lim_{n \to +\infty} f(x_{m(n)-k}) = \zeta.
\end{equation}
It follows from \eqref{eq:indu1} and \eqref{eq:indu2} that \eqref{eq:indu} holds for $k=1$. Suppose that \eqref{eq:indu} holds for $k=k_0$. Replacing $n$ by $ m(n)-k_0-1:= n_m$ in \eqref{eq:lsx} yields
\begin{align*}
&V(x_{m_n+1}, x_{m_n}, w_{m_n},\rho_{m_n}, \sigma_{m_n}) +c\|x_{m_n+1}-x_{m_n}\|^2 +d \|\nabla f(u_{m_n})\|^2+\delta\| w_{m_n}\| \notag\\
&\leq V(x_{m(m_n)}, x_{m(m_n)-1}, w_{m(m_n)-1},\rho_{m(m_n)-1},\sigma_{m(m_n)-1}).
\end{align*}
Using the definition of $V$, we have
\begin{align*}
&(c+ \rho_{m_n})\|x_{m_n+1}-x_{m_n}\|^2  +(\delta + \sigma_{m_n})\| w_{m_n}\| +d \|\nabla f(u_{m_n})\|^2 \notag\\
&\leq V(x_{m(m_n)}, x_{m(m_n)-1}, w_{m(m_n)-1},\rho_{m(m_n)-1},\sigma_{m(m_n)-1}) - f(x_{m_n+1}).
\end{align*}
Similar to the proof of \eqref{eq:indu1}, by the induction hypothesis (\eqref{eq:indu} holds with $k=k_0$) and \eqref{eq:limV}, we obtain that \eqref{eq:indu} holds for $k=k_0+1$, which completes the induction.

Next, let $n \geq N+1$. By the definition of $m(n)$, we have $n -N \leq m(n) \leq n$, and so $k_n := m(n) -(n -N) +1 \in [1, m(n)]$. Then $n-N = m(n) -k_n +1$ and by \eqref{eq:indu}, 
\begin{align*}
&\lim_{n \to +\infty}\|x_n-x_{n-1}\| = \lim_{n \to +\infty}\|x_{m(n)-k_n +1}-x_{m(n)-k_n}\| =0, \\
&\lim_{n \to +\infty}\|w_{n}\|=\lim_{n \to +\infty}\|w_{n-N-1}\| =\lim_{n \to +\infty}\|w_{m(n)-k_n}\|= 0, \text{~and}\\
&\lim_{n \to +\infty} f(x_{n}) =\lim_{n \to +\infty} f(x_{n-N-1}) = \lim_{n \to +\infty} f(x_{m(n)-k_n }) = \zeta.
\end{align*}
Combining this with the definition of $V$ and the boundedness of $\rho_n$ and $\sigma_n$, we deduce that
\begin{equation}\label{eq:limitf}
\lim_{n \to +\infty}V(x_{n}, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}) = \lim_{n \to +\infty}f(x_n) = \zeta.
\end{equation}
Take an arbitrary $\bar x \in \Omega$. Then there exists a sequence $(x_{k_n})_{n \in \N}$ such that $x_{k_n} \to \bar x$ as $n \to +\infty$. Since $f$ is continuous, we have $\lim_{n \to +\infty}f(x_{k_n}) =f(\bar x)$. This, together with \eqref{eq:limitf}, yields that $f(x_n) \to f(\bar x)$ and $V(x_{n}, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}) \to f(\bar x)$ as $n \to +\infty$.

\ref{t:subseq_simplify}: Since $\lambda_{n} \nabla f(u_n) = v_n- x_{n+1} + \mu w_n = -(x_{n+1} -x_n) + \gamma_n (x_n -x_{n-1}) + \mu w_n$, we have that
\begin{align*}
\lambda_{\min} \|\nabla f(u_n)\|\leq \lambda_n \|\nabla f(u_n)\| 
% &\leq \|x_{n+1} -x_n\| +\gamma_n\|x_n -x_{n-1}\| + \mu\|w_n\| \notag\\
\leq \|x_{n+1} -x_n\| +\bar\gamma\|x_n -x_{n-1}\| + \mu \|w_n\|.
\end{align*}
Combining with \ref{t:subseq_limit} yields $\lim_{n \to +\infty} \|\nabla f(u_n)\|=0$. Since $\nabla f$ is $L$-Lipschitz continuous, it holds that
\begin{equation*}
0\leq \left|\|\nabla f(u_n) \|-\|\nabla f(x_n)\|\right| \leq \|\nabla f(u_n) -\nabla f(x_n)\| \leq L\|u_n -x_n\| = L\beta_n\|x_n -x_{n-1}\|
\end{equation*}
which implies that $\lim_{n \to +\infty} \|\nabla f(x_n)\| =0$, and so $\lim_{n \to +\infty} \|\nabla f(\bar x)\| =0$ any $\bar x \in \Omega$. 

It follows from $\lim_{n \to +\infty}\|\nabla f(u_n)\| =0$ and $\lim_{n \to +\infty}\|w_n\| =0$ that there exists $N_0 \in \mathbb{N}$ such that, for all $n \geq N_0$, $\kappa_{\max} \|\nabla f(u_n)\| +\mu \bar\alpha \|w_{n-1}\| \leq \delta$. Combining this with Lemma~\ref{l:descent}\ref{l:descent_wn}, we have for all $n \geq N_0$, $w_n =0$, which yields $ x_{n+1} -v_n +\lambda_n \nabla f(u_n)=0$, where $u_n = x_n +\beta_n(x_n-x_{n-1})$ and $v_n = x_n +\gamma_n(x_n -x_{n-1})$.
\end{proof}

\begin{lemma}[Abstract convergence under KL property]
\label{l:KL}
Let $\mathcal{H}$ and $\mathcal{K}$ be two finite-dimensional real Hilbert
spaces. Let $h\colon \mathcal{K}\to \R$ be a continuous function, $(x_n)_{n\in \mathbb{N}}$ and $(z_n)_{n\in \mathbb{N}}$ be sequences in $\mathcal{H}$ and $\mathcal{K}$, respectively, $(\Delta_n)_{n\in \mathbb{N}}$ be a sequence of nonnegative real numbers, and $I$ be a finite set of integer indices with the smallest index not exceeding $1$. Set $\Delta_k =0$ for $k <0$ and consider the following conditions:
\begin{enumerate}
\renewcommand\theenumi{(\alph{enumi})}
\renewcommand{\labelenumi}{\rm (\alph{enumi})}
\item\label{a:decrease}
There exists a positive real number $\alpha$ such that, for all $n \in \N$, $h(z_{n+1}) + \alpha \Delta_n^2 \leq  h(z_n)$.
\item\label{a:error}
There exist nonnegative real numbers $\beta_i$, $i\in I$ such that, for all $n \in \N$, $\dist(0, \partial h(z_n)) \leq \sum_{i\in I} \beta_i\Delta_{n-i}$.
\item\label{a:distance}
There exists an integer $j$ such that, for all $n \in \N$, $\|x_{n+1} -x_n\| \leq  \Delta_{n+j}$.
\end{enumerate}
Suppose that \ref{a:decrease} and \ref{a:error} hold, that the sequence $(z_n)_{n \in \N}$ is bounded with $\Omega$ being the set of cluster points, and that $h$ satisfies the KL property at any point of $\Omega$. Then the following hold:
\begin{enumerate}
\item
For all $\bar z \in \Omega$, $0 \in \partial h(\bar z)$ and $h(z_n)\downarrow \bar h := h(\overline{z})$ as $n\to +\infty$.
\item 
If \ref{a:distance} holds, then $\sum_{n=0}^{+\infty} \|x_{n+1} -x_n\| < +\infty$ and the sequence $(x_n)_{n \in \N}$ converges to a point $\bar x \in \mathcal{H}$.
\item 
Suppose further that $h$ satisfies the KL property at any point of $\Omega$ with exponent $\alpha \leq 1/2$. Then there exist $\Gamma_1 \in \R_{++}$ and $\zeta \in (0,1)$ such that, for all $n \in \N$, $0 \leq h(z_n) - \bar h \leq \Gamma_1 \zeta^{n}$. Moreover, if \ref{a:distance} holds, then there exists $\Gamma_2 \in \R_{++}$ such that, for all $n \in \N$, $\|x_n -\bar x\| \leq \Gamma_2 \zeta^{n/2}.$
\end{enumerate}
\end{lemma}

\begin{proof}
In view of \cite[Lemma~5.1 and Theorem~5.2]{BDL21}, we only need to check that (I) there  exist a subsequence $(z_{k_n})_{n \in \N}$ and $\tilde{z}$ such that $z_{k_n} \to \tilde{z}$ and $h(z_{k_n}) \to h(\tilde{z})$ as $n \to +\infty$; and (II) $h$ is constant on $\Omega$. The first one is due to the continuity of $h$ and the boundedness of $(z_{n})_{n \in \N}$. We now check (II). It follows from \ref{a:decrease} that $(h(z_n))_{n \in \N}$ is nonincreasing, and hence convergent due to (I). Take an arbitrary $\bar z$ in $\Omega$. Then, there exists a subsequence $(z_{k_n})_{n \in \N}$ such that $z_{k_n} \to z$ as $n \to +\infty$. Since $h$ is continuous, we obtain that $h(\bar z) =\lim_{n \to +\infty} h(z_{k_n}) =\lim_{n\to +\infty} h(z_n)$, and so $h$ is constant on $\Omega$. The proof is complete.
\end{proof}

\begin{proof}
\ref{ADFGe:i}: According to Theorem~\ref{t:subseq}\ref{t:subseq_simplify}, there exists $N_0$ such that for all $n \geq N_0$, $w_{n} =0$ and $x_{n+1}=v_{n}-\lambda_n \nabla f(u_n)$. Let $n \geq N_0+1$. 
We first see that there exists $\underline{c} >0$ such that
\begin{equation}\label{eq:KL1}
V(x_{n+1}, x_n,0,\rho_n, \sigma_n)+ \underline{c} \|x_{n+1}-x_n\|^2  \leq V(x_n, x_{n-1},0,\rho_{n-1},\sigma_{n-1}).
\end{equation}
Indeed, since $N=0$, it follows from \eqref{eq:linesearch} that
\begin{equation}\label{eq:KL1'}
V(x_{n+1}, x_n,0,\rho_n, \sigma_n)+ c\|x_{n+1}-x_n\|^2  + d \|\nabla f(u_n)\|^2 \leq V(x_n, x_{n-1},0,\rho_{n-1},\sigma_{n-1}).
\end{equation}
By Step~\ref{step:init}, $d >0$ if $\lambda_{\min} >0$ and $c=0$. Thus, we must have $c >0$ or $d>0$ since $\lambda_{\min} >0$. If $c>0$, then \eqref{eq:KL1} holds with $\underline{c}:= c$. If $c=0$ and $d >0$, then by Step~\ref{step:main}, for all $n \in \N$, $\gamma_n =0$. Thus $x_{n+1} =x_n -\lambda_n \nabla f(u_n)$, which implies that $\|\nabla f(u_n)\| = \frac{1}{\lambda_n}\|x_{n+1} -x_n\| \geq \frac{1}{\lambda_{\max}}\|x_{n+1} -x_n\| $. This together with \eqref{eq:KL1'} implies that \eqref{eq:KL1} is satisfied with $\underline{c} := d/\lambda_{\max}^2$.

Set $\mathbf z_n = (x_{n}, x_{n-1}, \rho_{n-1})$. Noting that $g(x,y,s)=V(x,y,0,s,t)$, we have from \eqref{eq:linesearch} that
\begin{equation}\label{eq:KL_1}
g(\mathbf z_{n+1})+ \underline{c} \|x_{n+1}-x_n\|^2  \leq g(\mathbf z_n).
\end{equation}
On the other hand,
\begin{equation*}
\nabla g(\mathbf z_{n}) =(2\rho_{n-1}(x_{n} -x_{n-1}) + \nabla f(x_{n}), -2\rho_{n-1}(x_{n} -x_{n-1}) ,\|x_{n} -x_{n-1}\|^2 ).
\end{equation*}
Using the definition of $\rho_n$ and the fact that $\gamma_n \leq \bar\gamma$, $\nu_n \geq \underline{\nu}$, $L_n \leq L_{\max}$, we have
\begin{equation*}
\rho_n = \frac{1}{\mu^2}(1 -\mu \bar\alpha)\frac{\gamma_n}{\nu_n} + \frac{ L_n\beta_n +\gamma_n}{2 }\leq \frac{1}{\mu^2}(1 -\mu \bar\alpha)\frac{\bar\gamma}{\underline{\nu}} + \frac{ L_{\max}\bar\beta +\bar\gamma}{2 }=\bar\rho.
\end{equation*}
Therefore, by using the sum extension of the natural norm to the product space,
\begin{align}\label{eq:d1}
\|\nabla g(\mathbf z_{n})) \|&\leq \|2\rho_{n-1}(x_{n} -x_{n-1}) +\nabla f(x_{n})\| +\|2\rho_{n-1}(x_{n} -x_{n-1})\| +\|x_{n} -x_{n-1}\|^2 \notag\\
&\leq 4 \bar\rho\|x_{n} -x_{n-1}\| +\|\nabla f(x_{n})\| +\|x_{n} -x_{n-1}\|^2.
\end{align}
Since $\nabla f$ is $L$-Lipschitz continuous and $\beta_n \leq \bar\beta$,
\begin{equation*}
\|\nabla f(u_n) -\nabla f(x_n)\| \leq L \|u_n -x_n\| = L\|\beta_n(x_n -x_{n-1})\| \leq L \bar\beta\|x_n -x_{n-1}\|.
\end{equation*}
As $\lambda_n \nabla f(u_n) = v_n - x_{n+1} = -(x_{n+1} -x_n) + \gamma_n (x_n - x_{n-1})$, it follows that
\begin{align}\label{eq:d2}
\|\nabla f(x_n)\|& \leq \|\nabla f(u_n)\| + \|\nabla f(u_n) -\nabla f(x_n)\|\notag\\
% & \leq \frac{1}{\lambda_n}\|x_{n+1}-v_n\| + L \bar\beta\|x_n -x_{n-1}\| \notag\\
&\leq \frac{1}{\lambda_{\min}} (\|x_{n+1}-x_n\| + \bar\gamma\|x_n-x_{n-1}\|)  + L \bar\beta\|x_n -x_{n-1}\|  \notag\\
& =  \frac{1}{\lambda_{\min}}\|x_{n+1}-x_n\|  + \left( \frac{\bar\gamma}{\lambda_{\min}} +  L \bar\beta\right)\|x_n - x_{n-1}\|.
\end{align}
According to Theorem~\ref{t:subseq}\ref{t:subseq_limit}, $\lim_{n \to +\infty}\|x_{n}-x_{n-1}\| =0$, so there exists $N_1 \geq N_0 +1$ such that, for all $n \geq N_1$, $\|x_{n}-x_{n-1}\| \leq 1$, which implies that  $\|x_{n}-x_{n-1}\|^2 \leq \|x_{n}-x_{n-1}\|$. Combining this with \eqref{eq:d1} and \eqref{eq:d2}, there exists $C$ such that, for all $n \geq N_1$,
\begin{equation} \label{eq:KL2}
\| \nabla g(\mathbf z_{n}) \| \leq C(\|x_{n+1}-x_{n}\|+\|x_{n} -x_{n-1}\|).
\end{equation}
Moreover, $(\mathbf z_n)_{n \in \N}$ is bounded due to the boundedness of $(x_n)_{n \in \N}$ and $(\rho_n)_{n \in \N}$. Combining this with \eqref{eq:KL_1} and \eqref{eq:KL2}, we get the conclusion due to Lemma~\ref{l:KL}. 

\ref{ADFGe:ii}: As $\nabla f$ is $L$-Lipschitz continuous, for all $ n \in \N$,
\begin{align*}
&f(x_{n+1}) -f(x_n) -\frac{L}{2}\|x_{n+1}-x_n\|^2 \notag\\
&\leq \langle \nabla f(x_n), x_{n+1} -x_n\rangle  \notag\\
& = \langle\nabla f(x_n) -\nabla f(u_n), x_{n+1} -x_n\rangle + \langle \nabla f(u_n), x_{n+1} -x_n\rangle  \notag\\
& \leq L\|x_n -u_n\|\|x_{n+1} -x_n\| + \frac{1}{\lambda_n}\langle v_n -x_{n+1}, x_{n+1} -x_n \rangle \notag\\
& = L \beta_n \|x_n -x_{n-1}\|\|x_{n+1} -x_n\|- \frac{1}{\lambda_n}\| x_{n+1} -x_{n}\|^2 + \frac{\gamma_n}{\lambda_n}\langle x_n -x_{n-1}, x_{n+1} -x_n \rangle.
\end{align*}
Noting that $\langle x_n -x_{n-1}, x_{n+1} -x_n \rangle \leq \frac{1}{2}\left( \|x_n -x_{n-1}\|^2 + \|x_{n+1} -x_n\|^2 \right)$, we derive that
\begin{equation*}
f(x_{n+1}) -f(x_n) +\left(\frac{1}{\lambda_n} - \frac{L \beta_n}{2} -\frac{\gamma_n}{2\lambda_n}-\frac{L}{2} \right)\|x_{n+1}-x_n\|^2 \leq (\frac{L \beta_n}{2} +\frac{\gamma_n}{2\lambda_n})\|x_n - x_{n-1}\|^2.
\end{equation*}
Using the definition of $h$, we have
\begin{equation}\label{eq:cvKL2}
h(x_{n+1}, x_n) + \hat c \|x_{n+1}-x_n\|^2 \leq h(x_n,x_{n-1}),
\end{equation}
where $\hat c:= \frac{1}{\lambda_{\max} }- L \bar\beta -\frac{\bar\gamma}{\lambda_{\min}}-\frac{L}{2} >0$. On the other hand,
\begin{equation*}
\nabla h(x_n, x_{n-1}) = (\nabla f(x_{n}) + (L \bar\beta +\frac{\bar\gamma}{ \lambda_{\min} })(x_n -x_{n-1}),  -(L \bar\beta +\frac{\bar\gamma}{ \lambda_{\min} })(x_n -x_{n-1})).
\end{equation*}
Combining this with \eqref{eq:d2}, we obtain that
\begin{equation*}
\|\nabla h(x_n, x_{n-1})\| \leq  \frac{1}{\lambda_{\min}}\|x_{n+1}-x_n\|  + 3\left( \frac{\bar\gamma}{\lambda_{\min}} +  L \bar\beta\right)\|x_n - x_{n-1}\|,
\end{equation*}
which together with \eqref{eq:cvKL2} and Lemma~\ref{l:KL} completes the proof. 
\end{proof}

