Throughout this paper, $\mathcal{H}$ is a real Hilbert space equipped with the scalar product $\langle \cdot, \cdot\rangle$ and the associated norm $\|\cdot\|$. We consider the nonconvex optimization problem
\begin{equation}\label{eq:pb}
\min_{x \in \mathcal{H}} f(x),
\end{equation}

We denote the set of nonnegative integers by $\mathbb{N}$, the set of real numbers by $\mathbb{R}$, the set
of nonnegative real numbers by $\mathbb{R}_+$, and the set of the positive real numbers by $\mathbb{R}_{++}$. For $x\in \mathcal{H}$ and $\delta \in \mathbb{R}_+$, the closed ball in $\mathcal{H}$ centered at $x$ with radius $\delta$ is $B(x; \delta) = \{y \in \mathcal{H}: \|x - y\| \leq \delta\}$. For a subset $C$ of $\mathcal{H}$, its interior is $\inte C =\{x\in C: \exists \delta \in \mathbb{R}_{++},\ B(x; \delta) \subseteq C\}$.

Given $f\colon \mathcal{H} \to (-\infty, +\infty]$, its \emph{domain} is denoted by $\dom f =\{x \in \mathcal{H} \colon f(x)  < +\infty\}$ and its \emph{epigraph} by $\epi f =\{(x,\xi) \colon f(x) \leq \xi\}$. We say that $f$ is \emph{proper} if $\dom f \neq \varnothing$, \emph{lower semicontinuous} if $\epi f$ is a closed set, and \emph{convex} if $\epi f$ is a convex set. The function $f$ is said to be \emph{$\alpha$-weakly convex} ($\alpha \in \mathbb{R}_+$) if $f + \frac{\alpha}{2}\| \cdot\|^2$ is convex.

Let $f\colon \mathcal{H} \to (-\infty, +\infty]$ be proper and let $x \in \dom f$. The \emph{Fr\'echet subdifferential} of $f$ at $x$ is defined as
\begin{equation*}
\hat{\partial} f(x) = \left \{u \in \mathcal{H} \colon \liminf_{y \to x}\frac{f(y) -f(x) -\langle u, y-x \rangle}{\|y-x\|} \geq 0\right \}
\end{equation*}
and the \emph{limiting subdifferential} of $f$ at $x$ is defined as
\begin{equation*}
\partial f(x) = \{u \in \mathcal{H} \colon \exists x_n \to x, f(x_n) \to f(x) \text{~and~} \exists u_n \in \hat{\partial} f(x_n), u_n \to u \text{~as~} n \to +\infty\}.
\end{equation*}
For $x \notin  \dom f$, one takes $\hat{\partial} f(x)=\varnothing$ and $\partial f(x) = \varnothing$. The domain of $\partial f$ is $\dom \partial f = \{ x \in \mathcal{H}: \partial f(x) \neq \varnothing\}$. In the case when $f$ is convex, both Fr\'echet and limiting subdifferentials coincide with the \emph{convex subdifferential}, that is,
 $\partial f(x) =\{u \in \mathcal{H}: \forall y \in \mathcal{H}, \langle u, y-x\rangle \leq f(y) -f(x)\}.$

Let $\xi \in \R_{++}$. The \emph{Moreau envelope} of $f$ is the mapping $f_{\xi} \colon \mathcal{H} \to \left(-\infty, +\infty\right]$ given by
\begin{equation*}
f_{\xi}(x) = \inf_{y \in \mathcal{H}} \left(f(y) + \frac{1}{2\xi}\|x-y\|^2\right)
\end{equation*} 
and the \emph{proximal operator} of $f$ is the set-valued mapping $\prox_{\xi f} \colon  \mathcal{H} \rightrightarrows \mathcal{H}$ given by
\begin{equation*}
\prox_{\xi f}(x) =\argmin_{y \in \mathcal{H}}  \left(f(y) + \frac{1}{2\xi}\|x-y\|^2\right).
\end{equation*}
In a common abuse of notation, we consider $\prox_{\xi f}(x)$ as a point if it is a singleton.

\begin{definition}[Dry-like friction property]
\label{d:DLF}
We say that a proper function $\phi\colon \mathcal{H} \to \left(-\infty, +\infty\right]$ satisfies the \emph{dry-like friction property with constant $r \in \mathbb{R}_{++}$} if for all $x \in \dom \partial \phi$, $\inf_{u \in \partial \phi(x)} \langle u, x\rangle \geq r \|x\|$. The function $\phi$ is said to satisfy the \emph{dry-like friction property} or called a \emph{dry-like friction function} if it satisfies dry-like friction property with some constant $r$.
\end{definition}

\begin{align}\label{eq:V}
V(x,y,w,\rho,\sigma)= f(x) +\rho \|x -y\|^2 +\sigma \|w\|^2.
\end{align}

\begin{algo}[AGDNL]
\label{algo:AGDNL}
\step{}\label{step:init}
Let $\phi\colon \mathcal{H}\to \left(-\infty, +\infty\right]$ satisfy the dry-like friction property with constant $r$. 
Let $u_{-1}=x_{-1} =x_0 \in \mathcal{H}$. 
Let $\mu \in \R_{++}$, $\bar\alpha =\alpha_{-1} \in (0, \frac{1}{\mu})$,  $\bar\beta =\beta_{-1} \in \R_{+}$, and $\bar\gamma =\gamma_{-1} \in \R_{+}$. 
Let $L_{\min} \in (0, L]$, and $L_{\max} \in [L, +\infty)$. Let $\lambda_{\min} \in [0,\frac{1}{L_{\max}})$, $\lambda_{\max} \in [\lambda_{\min}, +\infty)$, $\kappa_{\min} \in (0, \bar\kappa]$, where $\bar\kappa = \frac{2(1-\mu \bar\alpha)}{\mu L_{\max}} -\frac{2(1-\mu \bar\alpha)\lambda_{\min}}{\mu}$, and $\kappa_{\max} \in [\kappa_{\min}, +\infty)$. Set 
\begin{equation*}
\bar c =\frac{2(1-\mu \bar \alpha) - \mu^2 L_{\max} \underline{\nu}}{2 \mu^2 \underline{\nu}} 
\text{~~and~~} \bar d =\frac{(1-\mu \bar\alpha)\lambda_{\min}^2 + \lambda_{\min} \mu \kappa_{\min}}{\mu^2 \underline{\nu}},    
\end{equation*}
where $\underline{\nu}=\frac{2 \lambda_{\min}(1 -\mu \bar\alpha)}{\mu^2}+ \frac{\kappa_{\min}}{\mu}$. Let $c \in [0, \bar c ]$ and $ d \in [0, \bar d]$ such that $d >0$ if $\lambda_{\min} >0$ and $c=0$. Let $L_{-1} \in [L_{\min}, L_{\max}]$, $\lambda_{-1} \in [\lambda_{\min}, \lambda_{\max}]$, $\kappa_{-1} \in [\kappa_{\min}, \kappa_{\max}]$, and set $\rho_{-1} = \frac{1}{\mu^2}(1 -\mu \bar\alpha)\frac{\gamma_{-1}}{\nu_{-1}} + \frac{L_{-1}\beta_{-1} +\gamma_{-1}}{2}$ and $\sigma_{-1} =\frac{\mu \alpha_{-1}}{2\nu_{-1}}$, where $\nu_{-1} = \frac{2\lambda_{-1}(1 -\mu \bar\alpha)}{\mu^2} +\frac{\kappa_{-1}}{\mu}$. 
Set also $w_{-1} =\frac{\lambda_{-1} \nabla f(u_{-1})}{\mu}$. Let $\delta \in \R_{++}$ and $\ell_1, \ell_2, \ell_3 \in (0,1)$. 
Let $N \in \N$ and set $n=0$.
%$d \in (0,\frac{(1- \mu \alpha)\lambda_{\min}^2}{\mu^2 \ell L_{\max}} )$ . 

\step{}\label{step:main}
Let $e_n \in \mathcal{H}$, $\theta_n \in \R$, and $\tau_n\in \mathbb{R}_+$ such that $r\tau_n \geq |\theta_n| +\|e_n\| +\delta$. 
Choose $\tilde{L}_n \in [L_{\min}, L_{\max}] $, $\tilde{\alpha}_n \in (0, \bar\alpha]$, and $\tilde{\kappa}_n \in [\kappa_{\min}, \kappa_{\max}]$. Choose $\tilde{\beta}_n \in [0, \bar\beta]$ such that $\tilde{\beta}_n  = 0$ if $c = \bar c$. %$\kappa_{\min} =\bar \kappa$. 
Choose $\tilde{\gamma}_n \in [0, \bar\gamma]$ such that $\tilde{\gamma}_n =0$ if $d=\bar d$ or $c=\bar c$ or $c=0$.
Choose $\tilde{\lambda}_n \in [\lambda_{\min}, \lambda_{\max}]$ such that $\tilde{\lambda}_n  =0$ if $\lambda_{\min} =0$. Set $\beta_n =\tilde{\beta}_n$, $\gamma_n =\tilde{\gamma}_n$, $L_n =\tilde{L}_n$, $\alpha_n =\tilde{\alpha}_n$, $\lambda_n =\tilde{\lambda}_n$, and $\kappa_n = \tilde{\kappa}_n$.
\begin{enumerate}[leftmargin=2em]
\item\label{step:main_comp}
Compute 
\begin{equation*}
\small
\begin{cases}
u_n = x_n + \beta_n(x_n - x_{n-1}),\\ 
%z_n &= x_n + \nu_n(x_n - x_{n-1}),\\
v_n = x_n + \gamma_n (x_n -x_{n-1}),\\
w_n \in \prox_{\tau_n \phi}\left(\alpha_n(x_n -v_{n-1}+\lambda_{n-1}\nabla f(u_{n-1}))-\theta_n \frac{\nabla f(u_n)}{\|\nabla f(u_n)\|} -\kappa_n \nabla f(u_n)+ e_n\right ),\\
z_{n+1} = v_n- \lambda_n\nabla f(u_n) +\mu w_n.
\end{cases}
\end{equation*}
\item 
\label{step:main_line}
Set $\rho_n = \frac{1}{\mu^2}(1 -\mu \bar\alpha)\frac{\gamma_n}{\nu_n} + \frac{ L_n\beta_n +\gamma_n}{2 }$ and $\sigma_n =\frac{\mu \alpha_n}{2 \nu_n}$, where $\nu_n = \frac{2 \lambda_n(1 -\mu \bar\alpha)}{\mu^2}+ \frac{\kappa_n }{\mu}$. If
\begin{align}\label{eq:linesearch}
V(z_{n+1}, x_n, w_n,\rho_n, \sigma_n) +c \|z_{n+1}-x_n\|^2 + d \|\nabla f(u_n)\|^2 +\frac{\delta}{\underline{\nu}}\| w_n\|\notag\\
\leq \max_{[n-N]_+ \leq k \leq n}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1}),
\end{align}
then go to Step~\ref{step:last}.
\item\label{step:main_mult}
Set $L_n \leftarrow \min\{L_n/\ell_1, L_{\max}\}$, $ \beta_n \leftarrow \ell_{2}\beta_n $,  $ \gamma_n \leftarrow \ell_{2}\gamma_n $, $\alpha_n \leftarrow \ell_{2}\alpha_n $, $\lambda_n \leftarrow \max\{\ell_3 \lambda_n, \lambda_{\min}\}$, $\kappa_n \leftarrow \max\{\ell_3 \kappa_n, \kappa_{\min}\}$, and go to Step~\ref{step:main}\ref{step:main_comp}. 
\end{enumerate}

\step{}\label{step:last}
Set $x_{n+1} \leftarrow z_{n+1}$. If a termination criterion is not met, then let $n\leftarrow n+1$ and go to Step~\ref{step:main}.
\end{algo}

\begin{equation}\label{AGNL}
\begin{cases}
u_n &= x_n + \beta_n(x_n - x_{n-1}),\\ 
v_n & = x_n + \gamma_n (x_n -x_{n-1}),\\
z_{n+1}\!\!\! &= v_n- \lambda_n\nabla f(u_n)
\end{cases}
\end{equation}

\begin{align}\label{AGNL_ls}
V(z_{n+1}, x_n, 0,\rho_n, \sigma_n) +c \|z_{n+1}-x_n\|^2 + d \|\nabla f(u_n)\|^2
\notag\\
\leq \max_{[n-N]_+ \leq k \leq n}V(x_k, x_{k-1}, 0,\rho_{k-1}, \sigma_{k-1}).    
\end{align}

We now recall the Kurdyka--{\L}ojasiewicz (KL) property \cite{Kur98, Loj63} which plays an important role in our convergence analysis. Let $h: \mathcal{H} \to (-\infty, +\infty]$ be a proper lower semicontinuous function. We say that $h$ satisfies the \emph{KL property} at $\bar x \in \dom \partial h$ if there exist $\varepsilon \in \mathbb{R}_{++}$, $\nu \in (0, +\infty]$, and a continuous concave function $\varphi: [0, \nu) \to \R_+$ such that $\varphi(0) =0$ and $\varphi$ is continuously differentiable on  $(0, \nu)$ with $\varphi' >0$, and for all $x \in B(\bar x; \varepsilon)$ with $h(\bar x) < h(x) < h (\bar x) + \nu$, one has
\begin{equation*}
\varphi'(h(x)- h(\bar x))\dist(0, \partial h(x)) \geq 1.
\end{equation*}
If $h$ satisfies the KL property at each point in $\dom \partial h$, then $h$ is called a \emph{KL function}.

The function $h$ is said to satisfy the \emph{KL property at $\bar x$ with exponent $\theta$} if it satisfies the KL property at $\bar x \in \dom \partial h$ with corresponding function $\varphi(s) = \gamma s^{1-\theta}$ for some $\gamma \in \R_{++}$ and $\theta \in [0,1)$, i.e., there exist $c \in \mathbb{R}_{++}$, $\varepsilon \in \mathbb{R}_{++}$, and $\nu \in (0, +\infty]$ such that
\begin{equation*}
\dist(0, \partial h(x)) \geq c (h(x) -h(\bar x))^{\theta}
\end{equation*}
whenever $x \in B(\bar x; \varepsilon)$ with $h(\bar x) < h(x) < h(\bar x) + \nu$. If $h$ is a KL function and has the same exponent $\theta$ at any $\bar x \in \dom \partial h$, then $h$ is called a \emph{KL function with exponent $\theta$}. Some typical KL functions include strongly convex functions, real analytic functions, and semialgebraic functions, see \cite{ABRS10, Loj63}.

\begin{theorem}[Sequential and linear convergence]
\label{t:fullseq}
Suppose that $\mathcal{H}$ is finite dimensional, that $f$ is a differentiable function whose gradient is $L$-Lipschitz continuous, and that $f$ is bounded below. Let $(x_n)_{n\in \mathbb{N}}$ be the sequence generated by AGDNL algorithm with $\lambda_{\min} >0$. Suppose further that the set $\{x \in \mathcal{H}: f(x) \leq f(x_0) + \sigma_{-1}\|w_{-1}\|^2\}$ is bounded, and that one of the following holds
\begin{enumerate}
\item \label{ADFGe:i}  $N=0$ and $ g(x,y,\rho):= f(x)+ \rho  \|x -y\|^2 $ satisfies the KL property at $(\bar x, \bar x, \rho)$ for all $\bar x \in \mathcal{H}$ and $\rho \in [0, \bar\rho]$, where $\bar\rho: =\frac{1}{\mu^2}(1 -\mu \bar\alpha)\frac{\bar\gamma}{\underline{\nu}} + \frac{ L_{\max}\bar\beta +\bar\gamma}{2 }$.
\item \label{ADFGe:ii} $\frac{1}{\lambda_{\max} }- L \bar\beta -\frac{\bar\gamma}{\lambda_{\min}}-\frac{L}{2} >0$ and $h(x,y) =f(x) +(\frac{L \bar\beta}{2} +\frac{\bar\gamma}{2 \lambda_{\min} }) \|x-y\|^2$ satisfies the KL property at $(\bar x, \bar x)$  for all $\bar x \in \mathcal{H}$.
\end{enumerate}
Then $\sum_{k=0}^{+\infty} \|x_{n+1} -x_n\| < +\infty$ and $(x_n)_{n\in \N}$ converges to a critical point $x^*$ of $f$. Moreover, if the KL property in \ref{ADFGe:i} or \ref{ADFGe:ii} is satisfied with exponent $\theta \leq 1/2$, then there exist $\Gamma \in \R_{++}$ and $\zeta \in (0,1)$ such that, for all $n \in \N$, $\|x_n -x^*\| \leq \Gamma{\zeta}^{n/2}$ and $|f(x_n) -f(x^*) |\leq \Gamma{\zeta}^n$.
\end{theorem}

\begin{proof}
\ref{ADFGe:i}: According to Theorem~\ref{t:subseq}\ref{t:subseq_simplify}, there exists $N_0$ such that for all $n \geq N_0$, $w_{n} =0$ and $x_{n+1}=v_{n}-\lambda_n \nabla f(u_n)$. Let $n \geq N_0+1$. 
We first see that there exists $\underline{c} >0$ such that
\begin{equation}\label{eq:KL1}
V(x_{n+1}, x_n,0,\rho_n, \sigma_n)+ \underline{c} \|x_{n+1}-x_n\|^2  \leq V(x_n, x_{n-1},0,\rho_{n-1},\sigma_{n-1}).
\end{equation}
Indeed, since $N=0$, it follows from \eqref{eq:linesearch} that
\begin{equation}\label{eq:KL1'}
V(x_{n+1}, x_n,0,\rho_n, \sigma_n)+ c\|x_{n+1}-x_n\|^2  + d \|\nabla f(u_n)\|^2 \leq V(x_n, x_{n-1},0,\rho_{n-1},\sigma_{n-1}).
\end{equation}
By Step~\ref{step:init}, $d >0$ if $\lambda_{\min} >0$ and $c=0$. Thus, we must have $c >0$ or $d>0$ since $\lambda_{\min} >0$. If $c>0$, then \eqref{eq:KL1} holds with $\underline{c}:= c$. If $c=0$ and $d >0$, then by Step~\ref{step:main}, for all $n \in \N$, $\gamma_n =0$. Thus $x_{n+1} =x_n -\lambda_n \nabla f(u_n)$, which implies that $\|\nabla f(u_n)\| = \frac{1}{\lambda_n}\|x_{n+1} -x_n\| \geq \frac{1}{\lambda_{\max}}\|x_{n+1} -x_n\| $. This together with \eqref{eq:KL1'} implies that \eqref{eq:KL1} is satisfied with $\underline{c} := d/\lambda_{\max}^2$.

Set $\mathbf z_n = (x_{n}, x_{n-1}, \rho_{n-1})$. Noting that $g(x,y,s)=V(x,y,0,s,t)$, we have from \eqref{eq:linesearch} that
\begin{equation}\label{eq:KL_1}
g(\mathbf z_{n+1})+ \underline{c} \|x_{n+1}-x_n\|^2  \leq g(\mathbf z_n).
\end{equation}
On the other hand,
\begin{equation*}
\nabla g(\mathbf z_{n}) =(2\rho_{n-1}(x_{n} -x_{n-1}) + \nabla f(x_{n}), -2\rho_{n-1}(x_{n} -x_{n-1}) ,\|x_{n} -x_{n-1}\|^2 ).
\end{equation*}
Using the definition of $\rho_n$ and the fact that $\gamma_n \leq \bar\gamma$, $\nu_n \geq \underline{\nu}$, $L_n \leq L_{\max}$, we have
\begin{equation*}
\rho_n = \frac{1}{\mu^2}(1 -\mu \bar\alpha)\frac{\gamma_n}{\nu_n} + \frac{ L_n\beta_n +\gamma_n}{2 }\leq \frac{1}{\mu^2}(1 -\mu \bar\alpha)\frac{\bar\gamma}{\underline{\nu}} + \frac{ L_{\max}\bar\beta +\bar\gamma}{2 }=\bar\rho.
\end{equation*}
Therefore, by using the sum extension of the natural norm to the product space,
\begin{align}\label{eq:d1}
\|\nabla g(\mathbf z_{n})) \|&\leq \|2\rho_{n-1}(x_{n} -x_{n-1}) +\nabla f(x_{n})\| +\|2\rho_{n-1}(x_{n} -x_{n-1})\| +\|x_{n} -x_{n-1}\|^2 \notag\\
&\leq 4 \bar\rho\|x_{n} -x_{n-1}\| +\|\nabla f(x_{n})\| +\|x_{n} -x_{n-1}\|^2.
\end{align}
Since $\nabla f$ is $L$-Lipschitz continuous and $\beta_n \leq \bar\beta$,
\begin{equation*}
\|\nabla f(u_n) -\nabla f(x_n)\| \leq L \|u_n -x_n\| = L\|\beta_n(x_n -x_{n-1})\| \leq L \bar\beta\|x_n -x_{n-1}\|.
\end{equation*}
As $\lambda_n \nabla f(u_n) = v_n - x_{n+1} = -(x_{n+1} -x_n) + \gamma_n (x_n - x_{n-1})$, it follows that
\begin{align}\label{eq:d2}
\|\nabla f(x_n)\|& \leq \|\nabla f(u_n)\| + \|\nabla f(u_n) -\nabla f(x_n)\|\notag\\
% & \leq \frac{1}{\lambda_n}\|x_{n+1}-v_n\| + L \bar\beta\|x_n -x_{n-1}\| \notag\\
&\leq \frac{1}{\lambda_{\min}} (\|x_{n+1}-x_n\| + \bar\gamma\|x_n-x_{n-1}\|)  + L \bar\beta\|x_n -x_{n-1}\|  \notag\\
& =  \frac{1}{\lambda_{\min}}\|x_{n+1}-x_n\|  + \left( \frac{\bar\gamma}{\lambda_{\min}} +  L \bar\beta\right)\|x_n - x_{n-1}\|.
\end{align}
According to Theorem~\ref{t:subseq}\ref{t:subseq_limit}, $\lim_{n \to +\infty}\|x_{n}-x_{n-1}\| =0$, so there exists $N_1 \geq N_0 +1$ such that, for all $n \geq N_1$, $\|x_{n}-x_{n-1}\| \leq 1$, which implies that  $\|x_{n}-x_{n-1}\|^2 \leq \|x_{n}-x_{n-1}\|$. Combining this with \eqref{eq:d1} and \eqref{eq:d2}, there exists $C$ such that, for all $n \geq N_1$,
\begin{equation} \label{eq:KL2}
\| \nabla g(\mathbf z_{n}) \| \leq C(\|x_{n+1}-x_{n}\|+\|x_{n} -x_{n-1}\|).
\end{equation}
Moreover, $(\mathbf z_n)_{n \in \N}$ is bounded due to the boundedness of $(x_n)_{n \in \N}$ and $(\rho_n)_{n \in \N}$. Combining this with \eqref{eq:KL_1} and \eqref{eq:KL2}, we get the conclusion due to Lemma~\ref{l:KL}. 

\ref{ADFGe:ii}: As $\nabla f$ is $L$-Lipschitz continuous, for all $ n \in \N$,
\begin{align*}
&f(x_{n+1}) -f(x_n) -\frac{L}{2}\|x_{n+1}-x_n\|^2 \notag\\
&\leq \langle \nabla f(x_n), x_{n+1} -x_n\rangle  \notag\\
& = \langle\nabla f(x_n) -\nabla f(u_n), x_{n+1} -x_n\rangle + \langle \nabla f(u_n), x_{n+1} -x_n\rangle  \notag\\
& \leq L\|x_n -u_n\|\|x_{n+1} -x_n\| + \frac{1}{\lambda_n}\langle v_n -x_{n+1}, x_{n+1} -x_n \rangle \notag\\
& = L \beta_n \|x_n -x_{n-1}\|\|x_{n+1} -x_n\|- \frac{1}{\lambda_n}\| x_{n+1} -x_{n}\|^2 + \frac{\gamma_n}{\lambda_n}\langle x_n -x_{n-1}, x_{n+1} -x_n \rangle.
\end{align*}
Noting that $\langle x_n -x_{n-1}, x_{n+1} -x_n \rangle \leq \frac{1}{2}\left( \|x_n -x_{n-1}\|^2 + \|x_{n+1} -x_n\|^2 \right)$, we derive that
\begin{equation*}
f(x_{n+1}) -f(x_n) +\left(\frac{1}{\lambda_n} - \frac{L \beta_n}{2} -\frac{\gamma_n}{2\lambda_n}-\frac{L}{2} \right)\|x_{n+1}-x_n\|^2 \leq (\frac{L \beta_n}{2} +\frac{\gamma_n}{2\lambda_n})\|x_n - x_{n-1}\|^2.
\end{equation*}
Using the definition of $h$, we have
\begin{equation}\label{eq:cvKL2}
h(x_{n+1}, x_n) + \hat c \|x_{n+1}-x_n\|^2 \leq h(x_n,x_{n-1}),
\end{equation}
where $\hat c:= \frac{1}{\lambda_{\max} }- L \bar\beta -\frac{\bar\gamma}{\lambda_{\min}}-\frac{L}{2} >0$. On the other hand,
\begin{equation*}
\nabla h(x_n, x_{n-1}) = (\nabla f(x_{n}) + (L \bar\beta +\frac{\bar\gamma}{ \lambda_{\min} })(x_n -x_{n-1}),  -(L \bar\beta +\frac{\bar\gamma}{ \lambda_{\min} })(x_n -x_{n-1})).
\end{equation*}
Combining this with \eqref{eq:d2}, we obtain that
\begin{equation*}
\|\nabla h(x_n, x_{n-1})\| \leq  \frac{1}{\lambda_{\min}}\|x_{n+1}-x_n\|  + 3\left( \frac{\bar\gamma}{\lambda_{\min}} +  L \bar\beta\right)\|x_n - x_{n-1}\|,
\end{equation*}
which together with \eqref{eq:cvKL2} and Lemma~\ref{l:KL} completes the proof. 
\end{proof}

\begin{lemma}\label{l:dry}
Suppose that $\phi\colon \mathcal{H}\to \left(-\infty, +\infty\right]$ satisfies the dry-like friction property with constant $r$. Let $y \in \mathcal{H}$ and $w \in \prox_{\tau \phi}(y)$. Then $\langle w-y, w\rangle  + r\tau \|w\| \leq 0.$
\end{lemma}

\begin{proof}
Since $w \in \prox_{\tau \phi}(y) = \argmin_{x \in \mathcal{H}} \left(\phi(x) +\frac{1}{2 \tau}\|x-y\|^2\right)$, we have $0 \in \partial \phi(w) + \frac{1}{\tau}(w-y)$, which yields $\frac{1}{\tau}(y-w) \in \partial \phi(w)$, and so $w \in \dom \partial \phi$. By the dry-like friction property of $\phi$, $\frac{1}{\tau}\langle y -w, w\rangle \geq r\|w\|$, which completes the proof.
\end{proof}

