\begin{theorem}[Subsequential convergence and structural simplification]
\label{t:subseq}
Let $(x_n)_{n\in \mathbb{N}}$ be the sequence generated by AGDNL algorithm and $\Omega$ be the set of strong cluster points of $(x_n)_{n \in \N}$. Suppose that $f$ is a differentiable function whose gradient is $L$-Lipschitz continuous, that $f$ is bounded below, and that the set $\{x \in \mathcal{H}: f(x) \leq f(x_0) + \sigma_{-1}\|w_{-1}\|^2\}$ is bounded. Then the following hold:
\begin{enumerate}
\item\label{t:subseq_bounded}
$(x_n)_{n \in \N}$ is bounded.
\item\label{t:subseq_limit} 
As $ n \to +\infty$, $\|x_{n+1}-x_n\| \to 0$,  $\|w_n\| \to 0$, $f(x_n) \to \zeta$, and \\ $V(x_{n}, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}) \to \zeta$ for some $\zeta \in \mathbb{R}$. Moreover, for all $\bar x \in \Omega$, $ f(\bar x) =\zeta$.  
\item\label{t:subseq_simplify} 
Suppose that $\lambda_{\min} >0$. Then $\lim_{n \to +\infty } \nabla f(x_n) =0$ and for all $\bar x \in \Omega$, $\nabla f(\bar x) =0$. Moreover, from some $N_0 \in \N$ onwards, $w_n =0$ and AGDNL algorithm becomes AGNL algorithm.
\end{enumerate}
\end{theorem}

\begin{proof}
\ref{t:subseq_bounded}: First, we prove by induction that, for all $n \in \N$,
\begin{equation}\label{eq:bx1}
V(x_{n}, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}) \leq f(x_0) + \sigma_{-1}\|w_{-1}\|^2.
\end{equation}
Since $x_{-1} =x_0$, we have $V(x_{0}, x_{-1}, w_{-1},\rho_{-1},\sigma_{-1}) = f(x_0) + \sigma_{-1}\|w_{-1}\|^2$, so \eqref{eq:bx1} holds for $n=0$. Suppose that \eqref{eq:bx1} holds for all $n \leq n_0$. %We have $\sigma_{-1} =0$ since $\alpha_{-1} =0$.
From \eqref{eq:linesearch}, we obtain that
\begin{align*}
V(x_{n_0+1}, x_{n_0}, w_{n_0},\rho_{n_0}, \sigma_{n_0}) &\leq \max_{[n_0-N]_+ \leq k \leq n_0}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1})\notag\\
&\leq   f(x_0) + \sigma_{-1}\|w_{-1}\|^2,
\end{align*}
and hence \eqref{eq:bx1} is satisfied for $n=n_0+1$, which completes the induction. Next, it follows from \eqref{eq:bx1} and the definition of $V$ that $f(x_n) \leq  f(x_0) + \sigma_{-1}\|w_{-1}\|^2$. The conclusion now follows from the boundedness of the set $\{x \in \mathcal{H}: f(x) \leq f(x_0) + \sigma_{-1}\|w_{-1}\|^2\}$.

\ref{t:subseq_limit}: It follows from the line search criterion \eqref{eq:linesearch} that
\begin{align}\label{eq:lsx}
&V(x_{n+1}, x_n, w_n,\rho_n, \sigma_n) +c\|x_{n+1}-x_n\|^2  + d \|\nabla f(u_n)\|^2+ \frac{\delta}{\underline{\nu}}\| w_n\|\notag\\ &\leq \max_{[n-N]_+ \leq k \leq n}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1})\notag\\
&= V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}).
\end{align}
Therefore,
\begin{align*}
&V(x_{m(n+1)}, x_{m(n)}, w_{m(n)},\rho_{m(n)}, \sigma_{m(n)}) \notag\\
&= \max_{[n+1-N]_+ \leq k \leq n+1}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1})\notag\\
&=\max \left\{V(x_{n+1}, x_n, w_n,\rho_n, \sigma_n), \max_{[n+1-N]_+ \leq k \leq n}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1}) \right\}\notag\\
& \leq  \max_{[n-N]_+ \leq k \leq n}V(x_k, x_{k-1}, w_{k-1},\rho_{k-1}, \sigma_{k-1}) \notag\\
&=V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}),
\end{align*}
which implies that the sequence $(V(x_{m(n+1)}, x_{m(n)}, w_{m(n)},\rho_{m(n)}, \sigma_{m(n)}))_{n\in \N}$ is nonincreasing. On the other hand, this sequence is bounded below due to the bounded below property of $f$ and the definition of $V$. Thus, there exists $\zeta$ such that
\begin{equation}\label{eq:limV}
\zeta =\lim_{n \to +\infty}V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}).
\end{equation} 
%\ref{t:subseq_limit}
In \eqref{eq:lsx}, replacing $n$ by $m(n)-1$ yields
\begin{align*}
&V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}) +c\|x_{m(n)}-x_{m(n)-1}\|^2 \notag\\ 
&+d \|\nabla f(u_{m(n)-1})\|^2 +\frac{\delta}{\underline{\nu}}\| w_{m(n)-1}\| \notag\\
&\leq V(x_{m(m(n)-1)}, x_{m(m(n)-1)-1}, w_{m(m(n)-1)-1},\rho_{m(m(n)-1)-1}, \sigma_{m(m(n)-1)-1}).
\end{align*}
Letting $n \to +\infty$ and noting that $m(n) \geq [n-N]_{+}$, we get $ \lim_{n \to +\infty}\|w_{m(n)-1} \| = 0$. 
If $c >0 $, we also have $\lim_{n \to +\infty}\|x_{m(n)}-x_{m(n)-1}\|~=~0$. If $c=0$ and $d >0$, then $\lim_{n \to +\infty}\|\nabla f(u_{m(n)-1}) \| = 0$, which implies that 
\begin{equation*}
 |x_{m(n)} - x_{m(n)-1}\| =\|-\lambda_{m(n)-1}\nabla f(u_{m(n)-1}) + \mu w_{m(n)-1} \| \to 0 \text{~as~} n \to +\infty   
\end{equation*}
If $c=d=0$, then $\lambda_{\min} =0$ since  $d >0$ if $\lambda_{\min} >0$ and $c=0$. By Step~\ref{step:main}, for all $n \in \N$, $\lambda_n = \gamma_n =0$, and so $\lim_{n \to +\infty}\|x_{m(n)}-x_{m(n)-1}\| =\lim_{n \to +\infty}\mu \|w_{m(n)-1} \| =0$. Therefore, in any cases,
\begin{equation}\label{eq:indu1}
\lim_{n \to +\infty}\|x_{m(n)}-x_{m(n)-1}\| = 0 \text{~and~} \lim_{n \to +\infty}\|w_{m(n)-1} \| = 0.
\end{equation}
By the definitions of $\rho_n$ and $\sigma_n$, for all $n \in \N$,
$0\leq \rho_n \leq  \frac{1}{\mu^2}(1 -\mu \bar\alpha)\frac{\bar\gamma}{\underline{\nu}} + \frac{ L_{\max}\bar\beta +\bar\gamma}{2 }$ and $ 0\leq  \sigma_n \leq\frac{\mu \alpha_{\max}}{2 \underline{\nu}}.$ Combining with \eqref{eq:limV} and \eqref{eq:indu1}, we derive that
\begin{align*}
f(x_{m(n)})&=V(x_{m(n)}, x_{m(n)-1}, w_{m(n)-1},\rho_{m(n)-1}, \sigma_{m(n)-1}) \notag\\
&\quad - \rho_{m(n)-1}\|x_{m(n)}-x_{m(n)-1}\|^2 - \sigma_{m(n)-1} \| w_{m(n)-1}\|^2
\end{align*}
also tends to $\zeta$ as $n \to +\infty$. Since $(x_n)_{n\in \N}$ is bounded and $\lim_{n \to +\infty}\|x_{m(n)}-x_{m(n)-1}\| = 0$, Lemma~\ref{l:limit} implies that 
\begin{equation}\label{eq:indu2}
\lim_{n \to +\infty}f(x_{m(n)-1})=\lim_{n \to +\infty}f(x_{m(n)}) = \zeta.
\end{equation}
Now, we prove by induction that for all $k \in [1, m(n)]$,
\begin{equation}\label{eq:indu}
\lim_{n \to +\infty}\|x_{m(n)-k+1}-x_{m(n)-k}\|=0 , \lim_{n \to +\infty} \|w_{m(n)-k}\|=0, \text{~and~} \lim_{n \to +\infty} f(x_{m(n)-k}) = \zeta.
\end{equation}
It follows from \eqref{eq:indu1} and \eqref{eq:indu2} that \eqref{eq:indu} holds for $k=1$. Suppose that \eqref{eq:indu} holds for $k=k_0$. Replacing $n$ by $ m(n)-k_0-1:= n_m$ in \eqref{eq:lsx} yields
\begin{align*}
&V(x_{m_n+1}, x_{m_n}, w_{m_n},\rho_{m_n}, \sigma_{m_n}) +c\|x_{m_n+1}-x_{m_n}\|^2 +d \|\nabla f(u_{m_n})\|^2+\delta\| w_{m_n}\| \notag\\
&\leq V(x_{m(m_n)}, x_{m(m_n)-1}, w_{m(m_n)-1},\rho_{m(m_n)-1},\sigma_{m(m_n)-1}).
\end{align*}
Using the definition of $V$, we have
\begin{align*}
&(c+ \rho_{m_n})\|x_{m_n+1}-x_{m_n}\|^2  +(\delta + \sigma_{m_n})\| w_{m_n}\| +d \|\nabla f(u_{m_n})\|^2 \notag\\
&\leq V(x_{m(m_n)}, x_{m(m_n)-1}, w_{m(m_n)-1},\rho_{m(m_n)-1},\sigma_{m(m_n)-1}) - f(x_{m_n+1}).
\end{align*}
Similar to the proof of \eqref{eq:indu1}, by the induction hypothesis (\eqref{eq:indu} holds with $k=k_0$) and \eqref{eq:limV}, we obtain that \eqref{eq:indu} holds for $k=k_0+1$, which completes the induction.

Next, let $n \geq N+1$. By the definition of $m(n)$, we have $n -N \leq m(n) \leq n$, and so $k_n := m(n) -(n -N) +1 \in [1, m(n)]$. Then $n-N = m(n) -k_n +1$ and by \eqref{eq:indu}, 
\begin{align*}
&\lim_{n \to +\infty}\|x_n-x_{n-1}\| = \lim_{n \to +\infty}\|x_{m(n)-k_n +1}-x_{m(n)-k_n}\| =0, \\
&\lim_{n \to +\infty}\|w_{n}\|=\lim_{n \to +\infty}\|w_{n-N-1}\| =\lim_{n \to +\infty}\|w_{m(n)-k_n}\|= 0, \text{~and}\\
&\lim_{n \to +\infty} f(x_{n}) =\lim_{n \to +\infty} f(x_{n-N-1}) = \lim_{n \to +\infty} f(x_{m(n)-k_n }) = \zeta.
\end{align*}
Combining this with the definition of $V$ and the boundedness of $\rho_n$ and $\sigma_n$, we deduce that
\begin{equation}\label{eq:limitf}
\lim_{n \to +\infty}V(x_{n}, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}) = \lim_{n \to +\infty}f(x_n) = \zeta.
\end{equation}
Take an arbitrary $\bar x \in \Omega$. Then there exists a sequence $(x_{k_n})_{n \in \N}$ such that $x_{k_n} \to \bar x$ as $n \to +\infty$. Since $f$ is continuous, we have $\lim_{n \to +\infty}f(x_{k_n}) =f(\bar x)$. This, together with \eqref{eq:limitf}, yields that $f(x_n) \to f(\bar x)$ and $V(x_{n}, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}) \to f(\bar x)$ as $n \to +\infty$.

\ref{t:subseq_simplify}: Since $\lambda_{n} \nabla f(u_n) = v_n- x_{n+1} + \mu w_n = -(x_{n+1} -x_n) + \gamma_n (x_n -x_{n-1}) + \mu w_n$, we have that
\begin{align*}
\lambda_{\min} \|\nabla f(u_n)\|\leq \lambda_n \|\nabla f(u_n)\| 
% &\leq \|x_{n+1} -x_n\| +\gamma_n\|x_n -x_{n-1}\| + \mu\|w_n\| \notag\\
\leq \|x_{n+1} -x_n\| +\bar\gamma\|x_n -x_{n-1}\| + \mu \|w_n\|.
\end{align*}
Combining with \ref{t:subseq_limit} yields $\lim_{n \to +\infty} \|\nabla f(u_n)\|=0$. Since $\nabla f$ is $L$-Lipschitz continuous, it holds that
\begin{equation*}
0\leq \left|\|\nabla f(u_n) \|-\|\nabla f(x_n)\|\right| \leq \|\nabla f(u_n) -\nabla f(x_n)\| \leq L\|u_n -x_n\| = L\beta_n\|x_n -x_{n-1}\|
\end{equation*}
which implies that $\lim_{n \to +\infty} \|\nabla f(x_n)\| =0$, and so $\lim_{n \to +\infty} \|\nabla f(\bar x)\| =0$ any $\bar x \in \Omega$. 

It follows from $\lim_{n \to +\infty}\|\nabla f(u_n)\| =0$ and $\lim_{n \to +\infty}\|w_n\| =0$ that there exists $N_0 \in \mathbb{N}$ such that, for all $n \geq N_0$, $\kappa_{\max} \|\nabla f(u_n)\| +\mu \bar\alpha \|w_{n-1}\| \leq \delta$. Combining this with Lemma~\ref{l:descent}\ref{l:descent_wn}, we have for all $n \geq N_0$, $w_n =0$, which yields $ x_{n+1} -v_n +\lambda_n \nabla f(u_n)=0$, where $u_n = x_n +\beta_n(x_n-x_{n-1})$ and $v_n = x_n +\gamma_n(x_n -x_{n-1})$.
\end{proof}

\ref{t:subseq_bounded}: First, we prove by induction that, for all $n \in \N$,
\begin{equation}\label{eq:bx1}
V(x_{n}, x_{n-1}, w_{n-1},\rho_{n-1}, \sigma_{n-1}) \leq f(x_0) + \sigma_{-1}\|w_{-1}\|^2.
\end{equation}
Since $x_{-1} =x_0$, we have $V(x_{0}, x_{-1}, w_{-1},\rho_{-1},\sigma_{-1}) = f(x_0) + \sigma_{-1}\|w_{-1}\|^2$, so \eqref{eq:bx1} holds for $n=0$. Suppose that \eqref{eq:bx1} holds for all $n \leq n_0$. %We have $\sigma_{-1} =0$ since $\alpha_{-1} =0$.
From \eqref{eq:linesearch}, we obtain that
\begin{align*}
